// Minimal replacement for internal/reflectlite on the tstst runtime.
// Type information comes from intrinsics generated by go2types.
package reflectlite

type Kind uint

const (
	Invalid Kind = iota
	Bool
	Int
	Int8
	Int16
	Int32
	Int64
	Uint
	Uint8
	Uint16
	Uint32
	Uint64
	Uintptr
	Float32
	Float64
	Complex64
	Complex128
	Array
	Chan
	Func
	Interface
	Map
	Pointer
	Slice
	String
	Struct
	UnsafePointer
)

const Ptr = Pointer

type Type interface {
	Name() string
	PkgPath() string
	Size() uintptr
	Kind() Kind
	Implements(u Type) bool
	AssignableTo(u Type) bool
	Comparable() bool
	String() string
	Elem() Type
}

type rtype struct{ id int }

// intrinsics (implemented by go2types)
func ifaceTypeID(i any) int
func typeKind(id int) int
func typeElem(id int) int
func typeString(id int) string
func typeImplements(id, iface int) bool
func typeComparable(id int) bool
func sliceSwap(s any, i, j int)
func ifacePtr(i any) int         // the pointer an interface holds
func memStore(t, p int, x any)   // stores x, whose dynamic type is t, at p
func memStoreIface(p int, x any) // stores the interface value x at p
func sliceLen(s any) int

func TypeOf(i any) Type {
	id := ifaceTypeID(i)
	if id == 0 {
		return nil
	}
	return rtype{id}
}

func (t rtype) Name() string     { return typeString(t.id) }
func (t rtype) PkgPath() string  { return "" }
func (t rtype) Size() uintptr    { return 8 }
func (t rtype) Kind() Kind       { return Kind(typeKind(t.id)) }
func (t rtype) String() string   { return typeString(t.id) }
func (t rtype) Comparable() bool { return typeComparable(t.id) }
func (t rtype) Elem() Type       { return rtype{typeElem(t.id)} }
func (t rtype) Implements(u Type) bool {
	return typeImplements(t.id, u.(rtype).id)
}
func (t rtype) AssignableTo(u Type) bool {
	uu := u.(rtype)
	if uu.id == t.id {
		return true
	}
	if Kind(typeKind(uu.id)) == Interface {
		return typeImplements(t.id, uu.id)
	}
	return false
}

// a Value holds i, or (from Elem) is the variable of type typ at ptr
type Value struct {
	i   any
	ptr int
	typ int
}

func ValueOf(i any) Value { return Value{i: i} }

func (v Value) Len() int { return sliceLen(v.i) }

func (v Value) Kind() Kind {
	if v.typ != 0 {
		return Kind(typeKind(v.typ))
	}
	id := ifaceTypeID(v.i)
	if id == 0 {
		return Invalid
	}
	return Kind(typeKind(id))
}

func (v Value) Type() Type {
	if v.typ != 0 {
		return rtype{v.typ}
	}
	return TypeOf(v.i)
}

func (v Value) IsNil() bool { return v.i == nil }

// Elem of a pointer held in an interface (what errors.As needs)
func (v Value) Elem() Value {
	if v.typ != 0 || v.Kind() != Pointer {
		panic("reflectlite: Value.Elem is only supported for pointers")
	}
	return Value{ptr: ifacePtr(v.i), typ: typeElem(ifaceTypeID(v.i))}
}

func (v Value) Set(x Value) {
	if v.typ == 0 {
		panic("reflectlite: Value.Set of an unaddressable value")
	}
	if Kind(typeKind(v.typ)) == Interface {
		memStoreIface(v.ptr, x.i)
	} else {
		memStore(v.typ, v.ptr, x.i)
	}
}

func (v Value) IsValid() bool { return v.i != nil || v.typ != 0 }

func Swapper(slice any) func(i, j int) {
	return func(i, j int) { sliceSwap(slice, i, j) }
}

type ValueError struct {
	Method string
	Kind   Kind
}

func (e *ValueError) Error() string { return "reflect: call of " + e.Method + " on zero Value" }
